"use client";

import { useEffect, useState } from "react";
import { optionalPurposeAllowed, subscribeConsentChange } from "@/lib/privacy/browser-consent";

const SCRIPT_ID = "chatbot-iframe";

/**
 * FastGPT embeddable widget.
 *
 * Injects FastGPT's official website embed loader
 * (`<script id="chatbot-iframe" src=".../js/iframe.js" data-bot-src=...>`)
 * exactly as generated by FastGPT → Publish → "Embed in website". The widget is
 * a floating launcher owned by FastGPT; it adds no page or section here.
 *
 * It is only mounted when the operator configured a share link
 * (NEXT_PUBLIC_FASTGPT_BOT_SRC) and the visitor has allowed functional
 * third-party features, because the iframe loads from the FastGPT host.
 */
export function FastGptWidget({ scriptSrc, botSrc, defaultOpen = false }: { scriptSrc: string; botSrc: string; defaultOpen?: boolean }) {
  const [allowed, setAllowed] = useState(false);

  useEffect(() => {
    const update = () => setAllowed(optionalPurposeAllowed("functional"));
    update();
    return subscribeConsentChange(update);
  }, []);

  useEffect(() => {
    if (!allowed || typeof document === "undefined") return;
    if (document.getElementById(SCRIPT_ID)) return;
    const script = document.createElement("script");
    script.id = SCRIPT_ID;
    script.type = "text/javascript";
    script.src = scriptSrc;
    script.defer = true;
    script.dataset.botSrc = botSrc;
    script.dataset.defaultOpen = defaultOpen ? "true" : "false";
    script.dataset.drag = "true";
    script.dataset.openIcon = "data:image/svg+xml;base64," + btoa('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="32" height="32"><rect x="4" y="6" width="24" height="18" rx="6" fill="#1f2937"/><circle cx="12" cy="15" r="2.2" fill="#f7f5ef"/><circle cx="20" cy="15" r="2.2" fill="#f7f5ef"/><path d="M12 25l-3 4 7-4z" fill="#1f2937"/></svg>');
    script.dataset.closeIcon = "data:image/svg+xml;base64," + btoa('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="32" height="32"><circle cx="16" cy="16" r="14" fill="#1f2937"/><path d="M10 10l12 12M22 10L10 22" stroke="#f7f5ef" stroke-width="3" stroke-linecap="round"/></svg>');
    document.body.appendChild(script);
    return () => {
      // Consent withdrawn: remove the loader and anything it mounted.
      document.getElementById(SCRIPT_ID)?.remove();
      document.getElementById("fastgpt-chatbot-button")?.remove();
      document.getElementById("fastgpt-chatbot-window")?.remove();
      document.getElementById("fastgpt-chatbot-container")?.remove();
    };
  }, [allowed, botSrc, defaultOpen, scriptSrc]);

  return null;
}
